double fa = f(a);
double fb = f(b);
if (fa * fb > 0) {
    throw std::invalid_argument("Root not bracketed");
}
unsigned int iter = 0;
while (std::abs(b - a) > precision && iter < max_iter) {
    double c = (a + b) / 2;
    double fc = f(c);
    if (fa * fc < 0) {
        b = c;
        fb = fc;
    } else {
        a = c;
        fa = fc;
    }
    iter++;
}
return (a + b) / 2;

